def shortest(N, edgeList):
    # Initialize distances array with infinity
    distances = [float('inf')] * N
    distances[0] = 0

    # Process each edge
    for _ in range(N - 1):
        for start, end, weight in edgeList:
            if distances[start] != float('inf') and distances[start] + weight < distances[end]:
                distances[end] = distances[start] + weight

    # Check for negative weight cycles (though not applicable here as weights are positive)
    for start, end, weight in edgeList:
        if distances[start] != float('inf') and distances[start] + weight < distances[end]:
            return -1

    # Return the distance to the last node
    return distances[N - 1] if distances[N - 1] != float('inf') else -1
